// pbdecode --protoc must print exactly what `protoc --decode_raw` prints, for valid and invalid input.
// Cases: messages generated by protobufjs, the same messages with random bytes changed, random bytes.
import protobuf from "protobufjs";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readdirSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const pbdecode = join(here, "..", "pbdecode.mjs");

// @protobuf-ts/protoc downloads the official protoc release on first use.
const require = createRequire(import.meta.url);
const protocPkg = dirname(require.resolve("@protobuf-ts/protoc/package.json"));
execFileSync(process.execPath, [join(protocPkg, "protoc.js"), "--version"], { stdio: "ignore" });
const installed = join(protocPkg, "installed");
const release = readdirSync(installed).find((d) => d.startsWith("protoc-"));
const protoc = join(installed, release, "bin", process.platform === "win32" ? "protoc.exe" : "protoc");

const root = protobuf.parse(`
syntax = "proto3";
message Inner { int32 id = 1; string name = 2; repeated double scores = 3; }
message Outer {
  uint64 big = 1; int32 neg = 2; sint32 zz = 3; bool flag = 4; double d = 5; float f = 6;
  fixed32 fx = 7; sfixed64 sfx = 8; string text = 9; bytes blob = 10; Inner inner = 11;
  repeated Inner items = 12; repeated int32 packed = 13; map<string, int64> tags = 14;
  repeated string names = 15; int64 big_neg = 16; uint32 u = 536870911;
}`).root;
const Outer = root.lookupType("Outer");

let seed = 42;
const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
const ri = (n) => Math.floor(rnd() * n);
const str = () => ["", "hello", "中文測試", 'a"b\\c\n', "x".repeat(ri(300))][ri(5)];
const inner = () => ({ id: ri(2) ? -ri(1e6) : ri(1e6), name: str(), scores: Array.from({ length: ri(4) }, () => rnd() * 1e6 - 5e5) });
const message = () => {
  const m = {};
  if (ri(2)) m.big = protobuf.util.Long.fromString(String(BigInt(ri(2 ** 31)) * 9999999n), true);
  if (ri(2)) m.neg = -ri(2 ** 31);
  if (ri(2)) m.zz = ri(1e6) - 5e5;
  if (ri(2)) m.flag = true;
  if (ri(2)) m.d = rnd() * 1e9 - 5e8;
  if (ri(2)) m.f = rnd() * 100;
  if (ri(2)) m.fx = ri(2 ** 31);
  if (ri(2)) m.sfx = protobuf.util.Long.fromNumber(-ri(1e12));
  if (ri(2)) m.text = str();
  if (ri(2)) m.blob = Buffer.from(Array.from({ length: ri(40) }, () => ri(256)));
  if (ri(2)) m.inner = inner();
  if (ri(2)) m.items = Array.from({ length: ri(4) }, inner);
  if (ri(2)) m.packed = Array.from({ length: ri(6) }, () => ri(1000) - 300);
  if (ri(2)) m.tags = Object.fromEntries(Array.from({ length: ri(3) }, () => [str().slice(0, 10), protobuf.util.Long.fromNumber(ri(1e9) - 5e8)]));
  if (ri(2)) m.names = Array.from({ length: ri(3) }, str);
  if (ri(2)) m.bigNeg = protobuf.util.Long.fromNumber(-ri(1e15));
  if (ri(2)) m.u = ri(2 ** 31);
  return m;
};
const encode = () => Buffer.from(Outer.encode(Outer.fromObject(message())).finish());

const work = mkdtempSync(join(tmpdir(), "pbdecode-"));
const run = (cmd, args, input) => {
  try {
    return { ok: true, out: execFileSync(cmd, args, { input, stdio: ["pipe", "pipe", "pipe"], maxBuffer: 1 << 30 }).toString().replace(/\r/g, "") };
  } catch {
    return { ok: false, out: "" };
  }
};
const failures = [];
const check = (label, buf) => {
  const file = join(work, "case.bin");
  writeFileSync(file, buf);
  const expected = run(protoc, ["--decode_raw"], buf);
  const actual = run(process.execPath, [pbdecode, file, "--protoc"]);
  const same = expected.ok === actual.ok && expected.out === actual.out;
  if (!same) failures.push(label);
  return same;
};

const groups = { generated: 0, mutated: 0, random: 0 };
const totals = { generated: 300, mutated: 500, random: 300 };
for (let i = 0; i < totals.generated; i++) if (check(`generated ${i}`, encode())) groups.generated++;
for (let i = 0; i < totals.mutated; i++) {
  const b = encode();
  if (b.length) for (let k = 0; k < 1 + ri(3); k++) b[ri(b.length)] = ri(256);
  if (check(`mutated ${i}`, b)) groups.mutated++;
}
for (let i = 0; i < totals.random; i++) if (check(`random ${i}`, Buffer.from(Array.from({ length: 1 + ri(64) }, () => ri(256))))) groups.random++;

console.log(`protoc ${release}`);
for (const k of Object.keys(groups)) console.log(`  ${k.padEnd(10)} ${groups[k]}/${totals[k]} identical`);
if (failures.length) {
  console.error(`FAILED: ${failures.slice(0, 10).join(", ")}`);
  process.exit(1);
}
